97	    func handle(_ message: ServerMessage) {
98	        switch message {
99	        case .ready, .audio, .audioEnd, .unknown:
100	            break  // Audio is WP1 tasks 6-7.
101	        case .state(let state, let label):
102	            if state == .thinking && orb != .thinking && orb != .searching {
103	                steps = []  // a new turn starts
104	                errorMessage = nil
105	            }
106	            if state == .searching, let label, steps.last != label {
107	                steps.append(label)
108	            }
109	            orb = state
110	            self.label = label
111	        case .transcript(let text):
112	            transcript = text
113	        case .reply(let reply):
114	            self.reply = reply
115	            surfaces = []
116	            errorMessage = nil
117	        case .a2ui(let messages):
118	            surfaces = Self.surfaces(from: messages)
119	            surfaces.forEach { $0.applyAppStyle(typeScale) }
120	        case .screenOK(let summary):
121	            showScreen(ScreenNotice(summary: summary))
122	        case .error(let message):
123	            errorMessage = message
124	        }
125	    }
