127	    /// Decodes one fixture frame through the same path as a live frame.
128	    func receive(_ frame: Data) {
129	        do {
130	            handle(try ServerMessage.decode(frame))
131	        } catch {
132	            print("fixture frame failed to decode: \(error)")
133	        }
