136	    /// One `SurfaceViewModel(catalog: basicCatalog)` per surface (contracts § A2UI).
137	    static func surfaces(from messages: [A2uiMessage]) -> [SurfaceViewModel] {
138	        var order: [String] = []
139	        var models: [String: SurfaceViewModel] = [:]
140	        for message in messages {
141	            let id = message.surfaceId
142	            if models[id] == nil {
143	                models[id] = SurfaceViewModel(catalog: basicCatalog)
144	                order.append(id)
145	            }
146	            let errors = models[id]?.processMessages([message]) ?? []
147	            for error in errors { print("a2ui \(id): \(error)") }
148	        }
149	        return order.compactMap { models[$0] }.filter { $0.componentTree != nil }
150	    }
