154	    private func showScreen(_ notice: ScreenNotice) {
155	        screen = notice
156	        screenExpiry?.cancel()
157	        screenExpiry = Task { [weak self] in
158	            try? await Task.sleep(for: Self.screenChipLifetime)
159	            guard !Task.isCancelled, self?.screen?.id == notice.id else { return }
160	            self?.screen = nil
161	        }
162	    }
