164	    /// Replays a fixture reply with the server's timing: thinking, a tool step, the
165	    /// reply and cards, then speaking until roughly when the spoken answer would end.
166	    private func runFixtureTurn(_ question: String) {
167	        fixtureTurn?.cancel()
168	        let turn = Fixtures.turn(for: question)
169	        fixtureTurn = Task { [weak self] in
170	            guard let self else { return }
171	            guard await fixtureStep(.thinking, wait: 0.9) else { return }
172	            guard await fixtureStep(.searching, turn.label, wait: 1.1) else { return }
173	            turn.frames.forEach(receive)
174	            let words = Double(reply?.say.split(separator: " ").count ?? 10)
175	            guard await fixtureStep(.speaking, wait: max(2, words * 0.32)) else { return }
176	            handle(.state(.idle, label: nil))
177	        }
178	    }
179	
180	    private func fixtureStep(_ state: OrbState, _ label: String? = nil, wait seconds: Double) async -> Bool {
181	        handle(.state(state, label: label))
182	        try? await Task.sleep(for: .seconds(seconds))
183	        return !Task.isCancelled
184	    }
185	}
